[
  {
    "type": "function",
    "name": "get_incoming_items",
    "description": "Listet die eingehenden Architektur-Items dieses Meetings (incomingItemId, text, sourceClaimIds), die aufgeloest werden muessen.",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "list_core_architecture",
    "description": "Listet die bestehenden Architektur-Entitaeten des Core als Kandidaten (entityId, identityKey, status, text).",
