        "decisions": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "incomingItemId": {
                "type": "string"
              },
              "decision": {
                "type": "string"
              },
              "reason": {
                "type": [
                  "string",
                  "null"
                ],
                "default": null
              }
            },
            "required": [
              "incomingItemId",
              "decision"
            ]
          }
        },
        "chainResume": {
          "type": "boolean",
          "default": true
